#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int num, score;
    char name[32];
    struct Node *next;
} Node;

Node *read_node(void) {
    Node *node = malloc(sizeof(*node));
    if (!node) exit(1);
    scanf("%d%31s%d", &node->num, node->name, &node->score);
    node->next = NULL;
    return node;
}

Node *creat(int count) {
    Node *head = NULL, **tail = &head;
    for (int i = 0; i < count; i++) {
        *tail = read_node();
        tail = &(*tail)->next;
    }
    return head;
}

void print(Node *head) {
    if (!head) puts("EMPTY");
    for (Node *p = head; p; p = p->next) printf("%d %s %d\n", p->num, p->name, p->score);
}

void destroy(Node *head) {
    while (head) { Node *next = head->next; free(head); head = next; }
}

int main(void) {
    Node *head = creat(3);
    print(head);
    destroy(head);
    return 0;
}
